      ],
      // 展示用户信息
      showMsg: {},
      fileList: [],
    }
  },
  computed: {
    filteredTableData() {
      return this.tableData3.filter(item =>
        item.businessName.includes(this.searchBusinessName) &&
        item.authorizationName.includes(this.searchAuthorizationName)
      );
    }
  },
  created() {

  },
  mounted() {
    this.getShowMsg()
  },
  methods: {
    // 上传前
    beforeUpload(file) {
      const isAkFile = file.name.endsWith('.ak');
      if (!isAkFile) {
        this.$message.error('请上传生成的 .ak 文件');
      }
      return isAkFile;
    },
    // // 提交数据时
    handleChange(file, fileList) {
      // 在上传前检查文件类型
      const isAkFile = file.name.endsWith('.ak'); // 只允许上传 .ak 文件
      if (!isAkFile) {
        this.$message.error('只能上传.ak文件！');
        return false; // 阻止文件上传
      }
      // 更新文件列表
      this.fileList = fileList;

      // 创建 FormData 对象
      const formData = new FormData();

      // 将文件添加到 FormData 中
      this.fileList.forEach(file => {
        formData.append('files', file.raw); // 'files[]' 是后端接收的字段名，依据实际情况调整
      });

      console.log("输出文件检查", formData);

      // 显示加载动画
      const loading = this.$loading({
        lock: true,               // 锁屏
        text: '正在上传文件...',   // 加载文字
        spinner: 'el-icon-loading', // 使用 Element 的加载图标
        background: 'rgba(0, 0, 0, 0.7)' // 背景颜色
      });

      // 使用 fetch 或 axios 提交 FormData
      fetch(activate.activateToLoad, {
        method: 'POST',
        body: formData
      })
        .then(response => response.json())
        .then(data => {
          // 关闭加载动画
          loading.close();

          // 成功提示
          // this.$message.success('文件上传成功！');
          // this.$message.success('正在前往登录页！');
          if (data.code == 200) {
            this.$message.success(data.msg)
            // 执行后续操作
            this.getShowMsg();
          } else {
            this.$message.warning(data.msg)
          }
          // console.log('上传结果:', data);

          setTimeout(() => {
            this.getJudgment();
          }, 3000);
        })
        .catch(error => {
          // 关闭加载动画
          loading.close();

          // 上传失败提示
          this.$message.error('上传失败！');
          console.error('上传错误:', error);
        });
    },
    // handleChange(file, fileList) {
    //   this.fileList = fileList; // 更新文件列表
    //   const formData = new FormData();

    //   // 将文件添加到 FormData 中
    //   this.fileList.forEach(file => {
    //     formData.append('files', file.raw); // 'files[]' 是后端接收的字段名，依据实际情况调整
    //   });
    //   console.log("输出文件检查",formData);


    //   // 使用 fetch 或 axios 提交 FormData
    //   fetch(activate.activateToLoad, {
