    //   .then(data => {
    //     this.$message.success('ak文件上传成功！');
    //     this.$message.success('正在前往登录页！');
    //     // console.log('上传结果:', data);
    //     this.getShowMsg();
    //     setTimeout(()=>{
    //       this.getJudgment();
    //     },1000)
    //   })
