    //   });
    // },
    submitUpload() {

    },
    handleClick(tab, event) {
      console.log(tab, event);
    },
    // 获取用户信息
    getShowMsg() {
      axios.get(activate.activateShow)
        .then(response => {
          this.showMsg = response.data.data[0]
          console.log(this.showMsg);

        })
        .catch(rek => {
          console.log(rek);
        })
    },
    formatDate(inputDateStr) {
      const date = new Date(inputDateStr);

      const options = {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      };

      // 格式化日期
      const formattedDate = date.toLocaleString('sv-SE', options).replace(' ', ' ');
      return formattedDate;
    },
    // 系统激活判断
    getJudgment() {
      this.$http.get(loginApi.activateJudgment)
        .then(response => {
          if (response.data.code == 200) {
            // this.activateOpen = false
            this.$router.push('/login')
          }
        })
        .catch(rek => {
          console.log(rek);
        })
    }
